-- Resolve columns to flattened row slots, and validate before any execution.
import Json (..)
import Model (..)
import Data.List (..)
import Data.Foldable (all, any, length)

fn check(e : Expr, columns : List(Column), allow : Bool, inside : Bool) : Expr =
  if e.op == "col" then
    let matches = filter(
        \(c) -> c.name == e.name && (e.qualifier == "" || e.qualifier == c.qualifier),
        columns,
      )
    demand(length(matches) > 0, "UNKNOWN_COLUMN")
    demand(length(matches) == 1, "AMBIGUOUS_COLUMN")
    let c = at(matches, 0)
    Expr {
      ..e,
      index = c.index,
      source = c.source,
      kind = c.kind,
      nullable = c.nullable
    }
  elif e.op == "lit" then
    e
  else
    let isagg = agg(e.op)
    demand(not(isagg) || allow && not(inside), "INVALID_AGGREGATION")
    let args = map(\(a) -> check(a, columns, allow, inside || isagg), e.args)
    let ts = map(\(a) -> a.kind, args)
    let kind =
      if e.op == "COUNT" then
        "int"
      elif elem(e.op, ["SUM", "+", "-", "*"]) then
        demand(all(\(t) -> compatible(t, "int"), ts), "TYPE_ERROR")
        "int"
      elif elem(e.op, ["MIN", "MAX"]) then
        demand(elem(at(ts, 0), ["int", "text", "null"]), "TYPE_ERROR")
        at(ts, 0)
      elif elem(e.op, ["NOT", "AND", "OR"]) then
        demand(all(\(t) -> compatible(t, "bool"), ts), "TYPE_ERROR")
        "bool"
      elif elem(e.op, ["ISNULL", "ISNOTNULL"]) then
        "bool"
      elif e.op == "COALESCE" then
        let known = filter(\(t) -> t /= "null", ts)
        if length(known) == 0 then
          "null"
        else
          demand(all(\(t) -> t == at(known, 0), known), "TYPE_ERROR")
          at(known, 0)
      else
        demand(
            compatible(at(ts, 0), at(ts, 1))
              && (not(elem("bool", ts)) || elem(e.op, ["=", "<>"])),
            "TYPE_ERROR",
          )
        "bool"
    Expr { ..e, args = args, kind = kind, nullable = nullability(e.op, args) }

-- Conservative static nullability; only used to license optimizer rewrites.
fn nullability(op : String, args : List(Expr)) : Bool =
  if elem(op, ["ISNULL", "ISNOTNULL", "COUNT"]) then
    false
  elif elem(op, ["SUM", "MIN", "MAX"]) then
    true
  elif op == "COALESCE" then
    all(\(a) -> a.nullable, args)
  else
    any(\(a) -> a.nullable, args)

fn predicate(e : Expr, columns : List(Column), allow : Bool) : Expr =
  let b = check(e, columns, allow, false)
  demand(compatible(b.kind, "bool"), "TYPE_ERROR")
  b

pub fn tree_any(p : (Expr) -> Bool, e : Expr) : Bool =
  p(e) || any(\(a) -> tree_any(p, a), e.args)

fn grouped(e : Expr, keys : List(Int)) : Unit =
  if not(agg(e.op)) then
    demand(e.op /= "col" || elem(e.index, keys), "INVALID_AGGREGATION")
    for a in sof(e.args) do
      grouped(a, keys)

fn find_table(database : List(Table), name : String) : Table =
  let ts = filter(\(t) -> t.name == name, database)
  demand(length(ts) > 0, "UNKNOWN_TABLE")
  at(ts, 0)

pub fn bind(q : Query, database : List(Table)) : Plan =
  let aliases = map(snd, q.select)
  demand(unique(aliases), "DUPLICATE_ALIAS")
  demand(unique(map(snd, q.sources)), "DUPLICATE_ALIAS")
  let tables = map(\(s) -> find_table(database, fst(s)), q.sources)
  var columns := []
  var joins := []
  for i in srange(0, length(tables)) do
    let t = at(tables, i)
    let offset = length(columns)
    let qualifier = snd(at(q.sources, i))
    let padded = i > 0 && at(q.outer, i - 1)
    let cs = map(
        \(k) -> Column { ..at(t.columns, k), index = offset + k, source = i, qualifier = qualifier, nullable = at(t.columns, k).nullable || padded },
        range(0, length(t.columns)),
      )
    columns := append(columns, cs)
    if i > 0 then
      joins := append(joins, [predicate(at(q.joins, i - 1), columns, false)])
  let cs = columns
  let sels = map(\(s) -> (check(fst(s), cs, true, false), snd(s)), q.select)
  let groups = map(\(e) -> check(e, cs, false, false), q.groups)
  let keys = map(\(e) -> e.index, groups)
  demand(unique(map(show_int, keys)), "INVALID_AGGREGATION")
  let pred = predicate(q.predicate, cs, false)
  let hav = predicate(q.having, cs, true)
  let roots = append(map(fst, sels), [hav])
  let aggregate =
    length(groups) > 0 || any(\(e) -> tree_any(\(n) -> agg(n.op), e), roots)
  demand(not(q.has_having) || aggregate, "INVALID_AGGREGATION")
  if aggregate then
    for e in sof(roots) do
      grouped(e, keys)
  let order = map(\(o) -> order_entry(aliases, o), q.order)
  let bq =
    Query {
      ..q,
      select = sels,
      joins = joins,
      groups = groups,
      predicate = pred,
      having = hav
    }
  Plan {
    query = bq,
    tables = tables,
    filters = map(\(_) -> [], tables),
    aggregate = aggregate,
    order = order
  }

fn alias_index(names : List(String), n : String, i : Int) : Int =
  match names of
    Nil =>
      reject("UNKNOWN_COLUMN")
      -1
    Cons(a, rest) =>
      if a == n then
        i
      else
        alias_index(rest, n, i + 1)

-- NULLS default to LAST ascending and FIRST descending; an explicit clause wins.
fn order_entry(
  aliases : List(String),
  o : (String, Bool, Int)
) : (Int, Bool, Bool) =
  match o of
    (n, desc, nulls) =>
      (
        alias_index(aliases, n, 0),
        desc,
        if nulls == 0 then desc else nulls == 1,
      )

-- The parser owns a scoped token-state effect; all ASTs are immutable values.
import Json (..)
import Data.String (..)
import Data.List (..)
import Data.Foldable (all, length)
import Model (..)
import Control.State (..)

pub type Token = Token { word: String, value: Json }

fn tok(s : String) : Token = Token { word = s, value = JNull }

fn scan_string(s : String, i : Int, acc : String) : (String, Int) =
  demand(i < byte_len(s), "PARSE_ERROR")
  if byte_at(s, i) == 39 then
    if i + 1 < byte_len(s) && byte_at(s, i + 1) == 39 then
      scan_string(s, i + 2, concat(acc, "'"))
    else
      (acc, i + 1)
  else
    scan_string(s, i + 1, concat(acc, str_of_char(chr(byte_at(s, i)))))

fn scan_word(s : String, i : Int, numbers : Bool) : Int =
  if i >= byte_len(s) then
    i
  else
    let c = byte_at(s, i)
    if (digit(c) || not(numbers) && (letter(c) || c >= 65 && c <= 90)) then
      scan_word(s, i + 1, numbers)
    else
      i

fn slice(s : String, i : Int, j : Int) : String =
  string_of_buf(slice_bytes(s, i, j, buf_empty()))

fn lex(s : String, i : Int) : List(Token) =
  if i >= byte_len(s) then
    [tok("$END")]
  else
    let c = byte_at(s, i)
    if elem(c, [32, 9, 10, 13]) then
      lex(s, i + 1)
    elif c == 39 then
      let (v, j) = scan_string(s, i + 1, "")
      Cons(Token { word = "LITERAL", value = JStr(v) }, lex(s, j))
    elif digit(c) then
      let j = scan_word(s, i, true)
      let n =
        match parse_int(slice(s, i, j)) of
          Some(v) => v
          None => 0
      Cons(Token { word = "NUMBER", value = JInt(n) }, lex(s, j))
    elif letter(c) || c >= 65 && c <= 90 then
      let j = scan_word(s, i, false)
      let w = slice(s, i, j)
      Cons(tok(if reserved(w) then to_upper(w) else w), lex(s, j))
    else
      let two = slice(s, i, min(i + 2, byte_len(s)))
      if elem(two, ["<>", "<=", ">="]) then
        Cons(tok(two), lex(s, i + 2))
      else
        demand(
            elem(c, [40, 41, 44, 46, 59, 43, 45, 42, 61, 60, 62]),
            "PARSE_ERROR",
          )
        Cons(tok(str_of_char(chr(c))), lex(s, i + 1))

fn peek() : String ! {State(List(Token))} = at(get(), 0).word

fn pop() : Token ! {State(List(Token)), Domain} =
  let ts = get()
  let t = at(ts, 0)
  demand(t.word /= "$END", "PARSE_ERROR")
  put(tail(ts))
  t

fn accept(w : String) : Bool ! {State(List(Token))} =
  if peek() == w then
    let ts = get()
    put(tail(ts))
    true
  else
    false

fn expect(w : String) : Unit = demand(accept(w), "PARSE_ERROR")

fn name() : String =
  let w = pop().word
  demand(name_ok(w), "PARSE_ERROR")
  w

fn natural() : Int =
  let t = pop()
  demand(t.word == "NUMBER", "PARSE_ERROR")
  integer(t.value)

fn reference() : Expr =
  let n = name()
  if accept(".") then
    column_ref(n, name())
  else
    column_ref("", n)

fn source() : (String, String) =
  let n = name()
  (n, if accept("AS") then name() else n)

fn precedence(op : String) : Int =
  if op == "OR" then
    1
  elif op == "AND" then
    2
  elif elem(op, ["=", "<>", "<", ">", "<=", ">="]) then
    4
  elif elem(op, ["+", "-"]) then
    5
  elif op == "*" then
    6
  else
    0

fn expression(minimum : Int) : Expr =
  let t = pop()
  let w = t.word
  let e =
    if w == "NOT" then
      node(w, [expression(3)])
    elif w == "(" then
      let x = expression(1)
      expect(")")
      x
    elif w == "-" then
      literal(JInt(-natural()))
    elif w == "NULL" then
      literal(JNull)
    elif elem(w, ["NUMBER", "LITERAL"]) then
      literal(t.value)
    elif elem(w, ["TRUE", "FALSE"]) then
      literal(JBool(w == "TRUE"))
    elif w == "COALESCE" then
      expect("(")
      let args = arguments()
      expect(")")
      demand(length(args) >= 2, "PARSE_ERROR")
      node(w, args)
    elif agg(w) then
      expect("(")
      let args =
        if w == "COUNT" && accept("*") then
          []
        else
          [expression(1)]
      expect(")")
      node(w, args)
    else
      demand(name_ok(w), "PARSE_ERROR")
      if accept(".") then
        column_ref(w, name())
      else
        column_ref("", w)
  binary(e, minimum, false)

fn arguments() : List(Expr) =
  let e = expression(1)
  Cons(e, if accept(",") then arguments() else [])

-- IS NULL / IS NOT NULL is an unambiguous postfix operator at comparison
-- precedence, so it composes freely; only chained binary comparisons are
-- refused, by `ordinary` below.
fn binary(left : Expr, minimum : Int, compared : Bool) : Expr =
  if peek() == "IS" && minimum <= 4 then
    let ignored = pop()
    let negated = accept("NOT")
    expect("NULL")
    binary(
        node(if negated then "ISNOTNULL" else "ISNULL", [left]),
        minimum,
        compared,
      )
  else
    ordinary(left, minimum, compared)

fn ordinary(left : Expr, minimum : Int, compared : Bool) : Expr =
  let op = peek()
  let p = precedence(op)
  if p < minimum then
    left
  else
    demand(not(p == 4 && compared), "PARSE_ERROR")
    let ignored = pop()
    let right = expression(p + 1)
    binary(node(op, [left, right]), minimum, compared || p == 4)

fn selections() : List((Expr, String)) =
  let e = expression(1)
  expect("AS")
  let a = name()
  Cons((e, a), if accept(",") then selections() else [])

fn group_keys() : List(Expr) =
  let e = reference()
  Cons(e, if accept(",") then group_keys() else [])

fn order_keys() : List((String, Bool, Int)) =
  let n = name()
  let desc = accept("DESC")
  if not(desc) then
    let ignored = accept("ASC")
    ()
  let nulls =
    if accept("NULLS") then
      if accept("FIRST") then
        1
      else
        expect("LAST")
        2
    else
      0
  Cons((n, desc, nulls), if accept(",") then order_keys() else [])

fn join_sources(
  ss : List((String, String)),
  js : List(Expr),
  os : List(Bool)
) : (List((String, String)), List(Expr), List(Bool)) =
  if elem(peek(), ["INNER", "JOIN", "LEFT"]) then
    let left = accept("LEFT")
    if left then
      let ignored = accept("OUTER")
      ()
    else
      let ignored = accept("INNER")
      ()
    expect("JOIN")
    let s = source()
    expect("ON")
    let e = expression(1)
    join_sources(append(ss, [s]), append(js, [e]), append(os, [left]))
  else
    (ss, js, os)

fn query() : Query =
  expect("SELECT")
  let distinct = accept("DISTINCT")
  let sels = selections()
  expect("FROM")
  let (ss, js, os) = join_sources([source()], [], [])
  let pred =
    if accept("WHERE") then
      expression(1)
    else
      literal(JBool(true))
  let groups =
    if accept("GROUP") then
      expect("BY")
      group_keys()
    else
      []
  let hh = accept("HAVING")
  let hav =
    if hh then
      expression(1)
    else
      literal(JBool(true))
  let order =
    if accept("ORDER") then
      expect("BY")
      order_keys()
    else
      []
  let lim =
    if accept("LIMIT") then
      natural()
    else
      -1
  let off =
    if lim >= 0 && accept("OFFSET") then
      natural()
    else
      0
  let ignored = accept(";")
  demand(peek() == "$END", "PARSE_ERROR")
  Query {
    select = sels,
    sources = ss,
    joins = js,
    outer = os,
    predicate = pred,
    groups = groups,
    having = hav,
    has_having = hh,
    order = order,
    distinct = distinct,
    limit = lim,
    offset = off
  }

pub fn parse_sql(s : String) : Query = eval_state(lex(s, 0), query)

-- The command protocol: view lifecycle, atomic batches, and the global
-- database revision. A command that fails leaves the session it was handed
-- untouched, because every update returns a new session value.
import Json (..)
import Model (..)
import Parser (..)
import Binder (..)
import Engine (..)
import Store (..)
import View (..)
import Data.List (..)
import Data.Foldable (all, length)

pub type Session = Session {
  tables: List(TableState),
  views: List(ViewState),
  revision: Int
}

pub fn new_session(database : List(Table)) : Session =
  Session { tables = map(initial_table, database), views = [], revision = 0 }

fn field_of(j : Json, key : String) : Json =
  match j of
    JObj(xs) =>
      let ms = filter(\(kv) -> fst(kv) == key, xs)
      if length(ms) == 1 then
        snd(at(ms, 0))
      else
        JNull
    _ => JNull

fn shape(j : Json, names : List(String)) : Unit =
  match j of
    JObj(xs) =>
      demand(length(xs) == length(names), "INVALID_COMMAND")
      demand(
          all(
              \(name) -> length(filter(\(kv) -> fst(kv) == name, xs)) == 1,
              names,
            ),
          "INVALID_COMMAND",
        )
    _ => reject("INVALID_COMMAND")

fn command_text(j : Json) : String =
  match j of
    JStr(s) => s
    _ =>
      reject("INVALID_COMMAND")
      ""

fn command_int(j : Json) : Int =
  match j of
    JInt(n) => n
    _ =>
      reject("INVALID_COMMAND")
      0

fn command_bool(j : Json) : Bool =
  match j of
    JBool(b) => b
    _ =>
      reject("INVALID_COMMAND")
      false

fn command_rows(j : Json) : List(Json) =
  match j of
    JArr(xs) => xs
    _ =>
      reject("INVALID_COMMAND")
      []

pub fn view_name_ok(s : String) : Bool =
  byte_len(s) >= 1
    && byte_len(s) <= 40
    && byte_at(s, 0) >= 97
    && byte_at(s, 0) <= 122
    && all(
        \(i) -> let c = byte_at(s, i) in c >= 97 && c <= 122 || digit(c) || c == 45,
        range(1, byte_len(s)),
      )

-- A change may name a table that does not exist, including a reserved SQL
-- word; that is a table error rather than a malformed command.
fn table_name_ok(s : String) : Bool =
  byte_len(s) > 0
    && letter(byte_at(s, 0))
    && all(
        \(i) -> letter(byte_at(s, i)) || digit(byte_at(s, i)),
        range(0, byte_len(s)),
      )

fn view_index(vs : List(ViewState), name : String) : Int = view_index_go(vs, name, 0)

fn view_index_go(vs : List(ViewState), name : String, i : Int) : Int =
  match vs of
    Nil => -1
    Cons(v, rest) =>
      if v.name == name then
        i
      else
        view_index_go(rest, name, i + 1)

fn validate_change(j : Json) : Change =
  let kind = command_text(field_of(j, "op"))
  demand(elem(kind, ["insert", "update", "delete"]), "INVALID_COMMAND")
  if kind == "delete" then
    shape(j, ["op", "table", "id"])
  else
    shape(j, ["op", "table", "id", "row"])
  let table = command_text(field_of(j, "table"))
  demand(table_name_ok(table), "INVALID_COMMAND")
  let id = command_int(field_of(j, "id"))
  demand(id >= 1 && id <= 2147483647, "INVALID_COMMAND")
  let cells =
    if kind == "delete" then
      []
    else
      command_rows(field_of(j, "row"))
  Change { kind = kind, table = table, id = id, cells = cells }

fn schemas(ts : List(TableState)) : List(Table) = map(\(t) -> t.schema, ts)

fn do_create(s : Session, cmd : Json) : (Session, Json) =
  shape(cmd, ["op", "view", "sql", "optimize"])
  let name = command_text(field_of(cmd, "view"))
  demand(view_name_ok(name), "INVALID_COMMAND")
  let sql = command_text(field_of(cmd, "sql"))
  let opt = command_bool(field_of(cmd, "optimize"))
  demand(view_index(s.views, name) < 0, "VIEW_EXISTS")
  let bound = bind(parse_sql(sql), schemas(s.tables))
  let plan = if opt then optimize(bound) else bound
  (
    Session { ..s, views = append(s.views, [create_view(name, plan, s.tables)]) },
    JObj([("view", JStr(name)), ("revision", JInt(s.revision))]),
  )

fn do_read(s : Session, cmd : Json) : (Session, Json) =
  shape(cmd, ["op", "view"])
  let name = command_text(field_of(cmd, "view"))
  demand(view_name_ok(name), "INVALID_COMMAND")
  let i = view_index(s.views, name)
  demand(i >= 0, "UNKNOWN_VIEW")
  let result = read_view(at(s.views, i))
  (
    s,
    JObj([
        ("revision", JInt(s.revision)),
        ("columns", getfield(result, "columns")),
        ("rows", getfield(result, "rows")),
      ]),
  )

fn do_drop(s : Session, cmd : Json) : (Session, Json) =
  shape(cmd, ["op", "view"])
  let name = command_text(field_of(cmd, "view"))
  demand(view_name_ok(name), "INVALID_COMMAND")
  let i = view_index(s.views, name)
  demand(i >= 0, "UNKNOWN_VIEW")
  (
    Session { ..s, views = filter(\(v) -> v.name /= name, s.views) },
    JObj([("dropped", JStr(name))]),
  )

-- Every shape is checked before any change is processed; the batch then runs
-- against a private copy of the tables and the views follow it in one step.
fn do_apply(s : Session, cmd : Json) : (Session, Json) =
  shape(cmd, ["op", "changes"])
  let raw = command_rows(field_of(cmd, "changes"))
  demand(length(raw) >= 1 && length(raw) <= 200, "INVALID_COMMAND")
  let changes = map(validate_change, raw)
  let (tables, deltas) = apply_changes(s.tables, changes)
  let revision = s.revision + 1
  (
    Session {
      tables = tables,
      views = map(\(v) -> apply_deltas(v, deltas), s.views),
      revision = revision
    },
    JObj([("revision", JInt(revision))]),
  )

pub fn run_command(s : Session, cmd : Json) : (Session, Json) =
  let op = command_text(field_of(cmd, "op"))
  if op == "create" then
    do_create(s, cmd)
  elif op == "read" then
    do_read(s, cmd)
  elif op == "drop" then
    do_drop(s, cmd)
  elif op == "apply" then
    do_apply(s, cmd)
  else
    reject("INVALID_COMMAND")
    (s, JNull)

fn reply(ok : Bool, body : Json) : Json =
  if ok then
    JObj([("ok", JBool(true)), ("result", body)])
  else
    JObj([("ok", JBool(false)), ("error", body)])

-- A rejected command reports its code and yields the session unchanged, so
-- earlier replies stay valid snapshots.
pub fn run_commands(start : Session, cmds : List(Json)) : List(Json) =
  var s := start
  var out := []
  for cmd in sof(cmds) do
    let step =
      handle run_command(s, cmd) with
        never reject(code) =>
          (s, reply(false, JObj([("code", JStr(code))])))
        return r => (fst(r), reply(true, snd(r)))
    s := fst(step)
    out := append(out, [snd(step)])
  out

-- One request, one response. Domain effects abort the complete query batch;
-- in command mode each command reports its own outcome instead.
import Json (..)
import Model (..)
import Parser (..)
import Binder (..)
import Engine (..)
import Session (..)
import Data.List (..)
import Data.Foldable (length)

fn validate_query(q : Json) : Unit =
  fields(q, ["sql", "optimize"])
  let ignored = text(getfield(q, "sql"))
  match getfield(q, "optimize") of
    JBool(_) => ()
    _ => reject("INVALID_INPUT")

-- The old and new request shapes are distinguished by their only other field;
-- carrying both, or neither, is malformed.
fn input_mode(input : Json) : String =
  match input of
    JObj(xs) =>
      let names = map(fst, xs)
      demand(
          length(names) == 2 && unique(names) && elem("database", names),
          "INVALID_INPUT",
        )
      if elem("queries", names) then
        "queries"
      elif elem("commands", names) then
        "commands"
      else
        reject("INVALID_INPUT")
        ""
    _ =>
      reject("INVALID_INPUT")
      ""

fn work(request : Json) : Json =
  demand(
      value_type(getfield(request, "protocol_version")) == "int"
        && integer(getfield(request, "protocol_version")) == 1,
      "INVALID_INPUT",
    )
  demand(text(getfield(request, "task")) == "query-null", "INVALID_INPUT")
  let input = getfield(request, "input")
  let mode = input_mode(input)
  let database = map(validate_table, arr(getfield(input, "database")))
  demand(unique(map(\(t) -> t.name, database)), "INVALID_INPUT")
  let results =
    if mode == "queries" then
      let queries = arr(getfield(input, "queries"))
      for q in sof(queries) do
        validate_query(q)
      map(
          \(q) -> let plan = bind(parse_sql(text(getfield(q, "sql"))), database) in execute(if truth(getfield(q, "optimize")) then optimize(plan) else plan),
          queries,
        )
    else
      let cmds = arr(getfield(input, "commands"))
      demand(length(cmds) <= 2000, "INVALID_INPUT")
      run_commands(new_session(database), cmds)
  JObj([("ok", JBool(true)), ("result", JObj([("results", JArr(results))]))])

fn error_response(code : String) : Json =
  JObj([("ok", JBool(false)), ("error", JObj([("code", JStr(code))]))])

fn decode_work(line : String) : Json =
  match decode_lossy(line) of
    Ok(request) => work(request)
    Err(_) => error_response("INVALID_INPUT")

fn main() =
  let line = read_line()
  let response =
    handle decode_work(line) with
      never reject(code) => error_response(code)
      return result => result
  println(encode(response))

